CREATE TABLE public.account_permission_changes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL,target_id uuid NOT NULL,before_data jsonb NOT NULL,after_data jsonb NOT NULL,reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.account_permission_changes TO authenticated;
GRANT ALL ON public.account_permission_changes TO service_role;
ALTER TABLE public.account_permission_changes ENABLE ROW LEVEL SECURITY;
CREATE POLICY permission_changes_read ON public.account_permission_changes FOR SELECT TO authenticated USING(private.is_super_admin(auth.uid()));
CREATE OR REPLACE FUNCTION private.supplement_permission_guard(u uuid) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF NOT private.is_active(auth.uid()) OR NOT(private.is_super_admin(auth.uid()) OR (private.is_admin(auth.uid()) AND private.has_permission(auth.uid(),'settings.user_custom_perm'))) THEN RAISE EXCEPTION 'Không có quyền tùy chỉnh quyền nhân sự.'; END IF;
 IF u=auth.uid() OR private.cleanup_is_biz_staff(u) OR EXISTS(SELECT 1 FROM profiles WHERE id=u AND is_system_admin) OR EXISTS(SELECT 1 FROM user_roles WHERE user_id=u AND role_id IN('role-admin','role-super-admin','role-kinh-doanh','role-9h328b84','role-g8qc3q2s','role-u0fzsvsp')) THEN RAISE EXCEPTION 'Tài khoản quản trị, Kinh doanh và tự thay đổi quyền được bảo vệ.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=u) THEN RAISE EXCEPTION 'Nhân sự không tồn tại.'; END IF;
END $$;
CREATE OR REPLACE FUNCTION private.supplement_permission_state(u uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('roles',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.role_id),'[]') FROM user_roles r WHERE r.user_id=u),'override',(SELECT to_jsonb(o) FROM user_permission_overrides o WHERE o.user_id=u)) $$;
CREATE OR REPLACE FUNCTION public.account_supplement_read(_target uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE state_ jsonb; BEGIN PERFORM private.supplement_permission_guard(_target);state_:=private.supplement_permission_state(_target); RETURN jsonb_build_object('fingerprint',md5(state_::text),'role_ids',(SELECT coalesce(jsonb_agg(role_id ORDER BY role_id),'[]') FROM user_roles WHERE user_id=_target AND source_kind='supplemental'),'permissions',(SELECT to_jsonb(permissions) FROM user_permission_overrides WHERE user_id=_target AND source_kind='supplemental'),'legacy_override',EXISTS(SELECT 1 FROM user_permission_overrides WHERE user_id=_target AND source_kind='legacy' AND use_custom),'roles',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',r.id,'name',r.name,'permissions',r.permissions) ORDER BY r.name),'[]') FROM app_roles r WHERE r.id NOT IN('role-admin','role-super-admin','role-kinh-doanh','role-9h328b84','role-g8qc3q2s','role-u0fzsvsp') AND NOT EXISTS(SELECT 1 FROM unnest(r.permissions)p WHERE p LIKE 'biz.%' OR p LIKE 'k3.%' OR p LIKE 'settings.%')));END $$;
CREATE OR REPLACE FUNCTION public.account_supplement_save(_target uuid,_roles text[],_permissions text[],_fingerprint text,_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE before_ jsonb; after_ jsonb; BEGIN
 LOCK TABLE user_roles,user_permission_overrides,app_roles,profiles,biz_appointments,biz_department_members,biz_management_assignments,biz_member_affiliations IN SHARE ROW EXCLUSIVE MODE;
 PERFORM private.supplement_permission_guard(_target);
 IF coalesce(length(trim(_reason)),0)=0 OR coalesce(cardinality(_roles),0)>30 OR coalesce(cardinality(_permissions),0)>600 THEN RAISE EXCEPTION 'Cần lý do và danh sách quyền hợp lệ.'; END IF;
 before_:=private.supplement_permission_state(_target); IF md5(before_::text) IS DISTINCT FROM _fingerprint THEN RAISE EXCEPTION 'Quyền đã thay đổi; tải lại trước khi lưu.'; END IF;
 IF EXISTS(SELECT 1 FROM user_permission_overrides WHERE user_id=_target AND source_kind='legacy' AND use_custom) THEN RAISE EXCEPTION 'Quyền riêng cũ chưa rõ nguồn — không ghi đè; cần đối chiếu ngoại lệ.'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(coalesce(_roles,'{}'))x WHERE NOT EXISTS(SELECT 1 FROM app_roles r WHERE r.id=x AND r.id NOT IN('role-admin','role-super-admin','role-kinh-doanh','role-9h328b84','role-g8qc3q2s','role-u0fzsvsp') AND NOT EXISTS(SELECT 1 FROM unnest(r.permissions)p WHERE p LIKE 'biz.%' OR p LIKE 'k3.%' OR p LIKE 'settings.%'))) THEN RAISE EXCEPTION 'Không được bổ sung Role quản trị hoặc Kinh doanh.'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(coalesce(_permissions,'{}'))p WHERE p LIKE 'biz.%' OR p LIKE 'k3.%' OR p LIKE 'settings.%' OR NOT EXISTS(SELECT 1 FROM base_permission_catalog WHERE key=p)) THEN RAISE EXCEPTION 'Không được bổ sung quyền quản trị, Kinh doanh hoặc quyền không tồn tại.'; END IF;
 DELETE FROM user_roles WHERE user_id=_target AND source_kind='supplemental' AND NOT(role_id=ANY(coalesce(_roles,'{}')));
 INSERT INTO user_roles(user_id,role_id,source_kind) SELECT _target,x,'supplemental' FROM (SELECT DISTINCT unnest(coalesce(_roles,'{}'))x)s ON CONFLICT DO NOTHING;
 INSERT INTO user_permission_overrides(user_id,use_custom,permissions,mode,source_kind) VALUES(_target,cardinality(coalesce(_permissions,'{}'))>0,ARRAY(SELECT DISTINCT unnest(coalesce(_permissions,'{}')) ORDER BY 1),'additive','supplemental') ON CONFLICT(user_id) DO UPDATE SET use_custom=excluded.use_custom,permissions=excluded.permissions,mode=excluded.mode,source_kind=excluded.source_kind,updated_at=now();
 after_:=private.supplement_permission_state(_target);
 INSERT INTO account_permission_changes(actor_id,target_id,before_data,after_data,reason) VALUES(auth.uid(),_target,before_,after_,_reason);
 RETURN jsonb_build_object('fingerprint',md5(after_::text),'saved',true); END $$;
REVOKE ALL ON FUNCTION private.supplement_permission_guard(uuid),private.supplement_permission_state(uuid) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.account_supplement_read(uuid),public.account_supplement_save(uuid,text[],text[],text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.account_supplement_read(uuid),public.account_supplement_save(uuid,text[],text[],text,text) TO authenticated,service_role;